// ════════════════════════════════════════════════════════════════
// getKanjiByLevel — returns all kanji for a given JLPT level
// ════════════════════════════════════════════════════════════════
export function getKanjiByLevel(level: 'N5' | 'N4' | 'N3' | 'N2'): KanjiItem[] {
  const dataset: KanjiItem[] = [...RAW_N5_KANJI];

  // N4 curriculum kanji (Lessons 26–50)
  const n4Data: Array<{ ch: string; lesson: number; onyomi: string[]; kunyomi: string[]; meanings: string[]; nepali: string[]; strokes: number; compounds: { word: string; reading: string; meaning: string }[] }> = [
    { ch: '行', lesson: 26, onyomi: ['KŌ', 'GYŌ'], kunyomi: ['i-ku', 'yu-ku'], meanings: ['Go'], nepali: ['जानु'], strokes: 6, compounds: [{ word: '旅行', reading: 'ryokō', meaning: 'Travel' }] },
    { ch: '来', lesson: 27, onyomi: ['RAI'], kunyomi: ['ku-ru', 'ko'], meanings: ['Come'], nepali: ['आउनु'], strokes: 7, compounds: [{ word: '来年', reading: 'rainen', meaning: 'Next year' }] },
    { ch: '帰', lesson: 28, onyomi: ['KI'], kunyomi: ['kae-ru'], meanings: ['Return'], nepali: ['फर्कनु'], strokes: 10, compounds: [{ word: '帰国', reading: 'kikoku', meaning: 'Return to country' }] },
    { ch: '食', lesson: 29, onyomi: ['SHOKU'], kunyomi: ['ta-beru'], meanings: ['Eat', 'Food'], nepali: ['खाउनु, खाना'], strokes: 9, compounds: [{ word: '食事', reading: 'shokuji', meaning: 'Meal' }] },
    { ch: '飲', lesson: 30, onyomi: ['IN'], kunyomi: ['no-mu'], meanings: ['Drink'], nepali: ['पिउनु'], strokes: 12, compounds: [{ word: '飲み物', reading: 'nomimono', meaning: 'Beverage' }] },
    { ch: '見', lesson: 31, onyomi: ['KEN'], kunyomi: ['mi-ru'], meanings: ['See', 'Look'], nepali: ['हेर्नु'], strokes: 7, compounds: [{ word: '意見', reading: 'iken', meaning: 'Opinion' }] },
    { ch: '聞', lesson: 32, onyomi: ['BUN', 'MON'], kunyomi: ['ki-ku'], meanings: ['Listen', 'Hear'], nepali: ['सुन्नु'], strokes: 14, compounds: [{ word: '新聞', reading: 'shinbun', meaning: 'Newspaper' }] },
    { ch: '読', lesson: 33, onyomi: ['DOKU'], kunyomi: ['yo-mu'], meanings: ['Read'], nepali: ['पढ्नु'], strokes: 14, compounds: [{ word: '読書', reading: 'dokusho', meaning: 'Reading' }] },
    { ch: '書', lesson: 34, onyomi: ['SHO'], kunyomi: ['ka-ku'], meanings: ['Write'], nepali: ['लेख्नु'], strokes: 10, compounds: [{ word: '図書館', reading: 'toshokan', meaning: 'Library' }] },
    { ch: '話', lesson: 35, onyomi: ['WA'], kunyomi: ['hana-su'], meanings: ['Speak', 'Talk'], nepali: ['बोल्नु'], strokes: 13, compounds: [{ word: '電話', reading: 'denwa', meaning: 'Telephone' }] },
  ];

  n4Data.forEach(({ ch, lesson, onyomi, kunyomi, meanings, nepali, strokes, compounds: cpds }) => {
    dataset.push({
      character: ch,
      level: 'N4',
      lessonOrder: lesson,
      strokeCount: strokes,
      readingsOnyomi: onyomi,
      readingsKunyomi: kunyomi,
      meanings,
      meaningsNepali: nepali,
      radicals: [{ radical: ch, meaning: meanings[0], color: '#ffb703' }],
      compounds: cpds,
    });
  });

  // N3 curriculum kanji (Lessons 51–75)
  const n3Chars = ['政', '議', '民', '連', '対', '部', '合', '市', '内', '相'];
  n3Chars.forEach((ch, idx) => {
    dataset.push({
      character: ch,
      level: 'N3',
      lessonOrder: Math.floor(idx * 2.4) + 51,
      strokeCount: 8 + (idx % 5),
      readingsOnyomi: [['SEI', 'GI', 'MIN', 'REN', 'TAI', 'BU', 'GŌ', 'SHI', 'NAI', 'SŌ'][idx]],
      readingsKunyomi: [],
      meanings: [['Politics', 'Meeting', 'People', 'Connect', 'Target', 'Section', 'Combine', 'City', 'Inside', 'Minister'][idx]],
      meaningsNepali: [['राजनीति', 'बैठक', 'जनता', 'सम्पर्क', 'लक्ष्य', 'विभाग', 'मिलाउनु', 'सहर', 'भित्र', 'मन्त्री'][idx]],
      radicals: [{ radical: ch, meaning: 'N3 Kanji', color: '#3b82f6' }],
      compounds: [],
    });
  });

  return dataset.filter(k => k.level === level).sort((a, b) => a.lessonOrder - b.lessonOrder);
}

export function getKanjiByLevelAndLesson(level: 'N5' | 'N4' | 'N3' | 'N2', lessonNumber?: number): KanjiItem[] {
  const fullLevel = getKanjiByLevel(level);
  if (lessonNumber) {
    return fullLevel.filter(k => k.lessonOrder === lessonNumber);
  }
  return fullLevel;
}
